from __future__ import print_function
from builtins import object
import os
import re
from taf.ul.trs_e2e_fw.lib.ipsec.command_builder import CommandBuilder
from taf.ul.trs_e2e_fw.lib.ipsec.exceptions import IpSecConnectionError
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.scf_parser.scf_parser import ScfParser
from taf.ul.trs_e2e_fw.lib.utils.connection_manager.communicator import Communicator
from taf.ul.trs_e2e_fw.lib.ipsec.ipsec_validate import ipsec_validate
from taf.ul.trs_e2e_fw.lib.ipsec.ipsec_utils import ipsec_utils
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler

logger = BackgroundLogger.Instance()


class ipsec_secgw(object):
    """ All secgw Ipsec methods in this class"""

    def __init__(self):
        self.cmd_builder = CommandBuilder()
        self.config = ConfigHandler.get_config()
        self.comunicator_obj = Communicator()
        self.ipsec_val_obj = ipsec_validate()
        self.ipsec_util = ipsec_utils()

    def ipsec_config(self):
        """ipsec config"""
        pass

    def enable_ipsec_on_secgw(self, device="default"):
        """Enables Ipsec on secgw"""
        ret = self.ipsec_util.execute_command_on_secgw('sudo ipsec start', device)
        logger.debug(ret)

    def disable_ipsec_on_secgw(self, device="default"):
        """Stops ipsec on secgw"""
        self.ipsec_util.execute_command_on_secgw('sudo ipsec stop', device)

    def ipsec_secgw_restart(self, device="default"):
        """Restarts ipsec on secgw"""
        self.ipsec_util.execute_command_on_secgw('sudo ipsec restart', device)

    def verify_connections_established(self, conn):
        """ Raises exception if connections are not established on Secgw """
        states = self.get_connections_states(conn)
        if any((status == 'not established' or espspi is None for status, espspi in
                list(states.values()))):
            raise IpSecConnectionError('On Secgw', states)

    def get_connections_states(self, conn=(50, 60, 70)):
        """Returns connection(s) status"""
        console_output = self.get_ipsec_status()
        return self.ipsec_util.parse_connections_states(conn, console_output)

    def get_conn_name_from_ipsec_param(self, parameter, value, device):
        """Get connection name from ipsec param"""
        conNameList = self.get_all_connections(device)
        conDict = {}
        for conn in conNameList:
            awkcommand_template = self.cmd_builder.build_awk_command_to_get_params()
            awkcommand = awkcommand_template.format(conn_num=conn, param=parameter,
                                                    conf_file=get_config_variable(
                                                        ["ipsec_conf_path"]))
            # print awkcommand
            try:
                result = self.ipsec_util.execute_command_on_secgw(awkcommand, device)
                paramValue = result.splitlines()[0].split("=")[1]
                conDict[conn] = paramValue
            except Exception:
                pass
        connections = []
        for conn, paramvalue in list(conDict.items()):
            if value == paramvalue:
                logger.info(conn)
                connections.append(conn)
        logger.info(connections)
        return connections

    def get_all_connections(self, device):
        """get all connections"""
        awkcommand_template = self.cmd_builder.build_awk_command_for_all_connections()
        awkcommand = awkcommand_template.format(conf_file=get_config_variable(["ipsec_conf_path"]))
        # print awkcommand
        result = self.ipsec_util.execute_command_on_secgw(awkcommand, device)
        conList = result.splitlines()
        conNameList = []
        for con in conList:
            conNameList.append(con.split(" ")[1])
        return conNameList

    def common_conn_list(self, list1, list2):
        """Common connection list"""
        return list(set(list1) & set(list2))

    def restore_old_ipsec_conf_on_secgw(self, device):
        """Modifies Ipsec policy parameters for the specified connection(s) with the specified
        parameter name & values on Secgw"""
        self.ipsec_util.execute_command_on_secgw('cp {conf_file} {back_file}'.format(
            back_file='/tmp/ipsec_conf.bkp',
            conf_file=get_config_variable(["ipsec_conf_path"])), device)

    def ipsec_verify_status_with_scfc(self, scfc_file):
        """Verify ipsec status with scfc"""
        bts = get_config_variable(["bts"])
        ipsec_status_bts = self.comunicator_obj.execute_commands_remotely_and_verify(
            bts["ip"], bts["username"], bts["password"], 'ipsec status')
        local_ip_list = self._get_list_of_ips('localIp', 'SECPOL', scfc_file)
        local_length = self._get_list_of_ips('localIpPrefixLength', 'SECPOL', scfc_file)
        remote_ip_list = self._get_list_of_ips('remoteIp', 'SECPOL', scfc_file)
        remote_length = self._get_list_of_ips('remoteIpPrefixLength', 'SECPOL', scfc_file)
        local_tunnel_list = self._get_list_of_ips('localTunnelEndPoint', 'IKEP', scfc_file)
        count_secpol = len(local_ip_list)
        count_ikep = len(local_tunnel_list)
        self.ipsec_val_obj.check_if_installed(ipsec_status_bts, count_ikep, count_secpol,
                                              local_ip_list, local_length, remote_ip_list,
                                              remote_length)

    def _edit_ipsec_conf_file(self, conn, parameter, value, device):
        self.ipsec_conf_path = self._get_ipsec_conf_path(device)
        sedcommand = self.cmd_builder._build_sed_command(conn, parameter, value)
        logger.info(sedcommand)
        self.ipsec_util.execute_command_on_secgw(sedcommand, device)

    def _interpret_connection_numbers(self, connections, device):
        if connections[0].strip().lower() == 'all':
            config_connections = []
            for conn in get_config_variable(["ipsec_devices", device, "connections"]):
                config_connections.append(conn.format(btsid=get_config_variable(["bts_id"])))
            return config_connections
        elif connections[0].strip().lower() == 'default':
            return [r'\%default']
        else:
            connections = [conn for conn in connections]
            logger.info(connections)
            return connections

    def _get_ipsec_conf_path(self, device):
        ipsec_bin_file = self.ipsec_util.execute_command_on_secgw('which ipsec', device)
        ipsec_bin_file = ipsec_bin_file.replace('\n', '')
        ipsec_conf_path = self.ipsec_util.execute_command_on_secgw(
            'cat {} | grep IPSEC_CONFDIR= | cut -d\'=\' -f2'.format(ipsec_bin_file), device)
        ipsec_conf_path = ipsec_conf_path.replace('"', '')
        ipsec_conf_path = ipsec_conf_path.replace('\n', '')
        ipsec_conf_path = os.path.join(ipsec_conf_path, get_config_variable(["ipsec_conf_file"]))
        return ipsec_conf_path

    def _get_list_of_ips(self, parameter, classname, scfc_file):
        scf_obj = ScfParser(scfc_file)
        nodes = scf_obj.get_list_by_classname(classname)
        paramList = []
        secpol_ip_regex = {"localIp": './/p[@name="localIpAddress"]',
                           "localIpPrefixLength": './/p[@name="localIpPrefixLength"]',
                           'remoteIp': './/p[@name="remoteIpAddress"]',
                           "remoteIpPrefixLength": './/p[@name="remoteIpPrefixLength"]'}
        if classname == "SECPOL":
            for node in nodes:
                ipsecAction = re.search("PROTECT", node.find('.//p[@name="ipSecAction"]').text)
                logger.info(ipsecAction)
                # paramList = self._secpol_data(node, paramList, parameter)
                if parameter in secpol_ip_regex:
                    paramList.append(node.find(secpol_ip_regex.get(parameter)).text)
        else:
            othe_ip_regex = {"localTunnelEndPoint": './/p[@name="localTunnelEndpoint"]',
                             "remoteTunnelEndPoint": './/p[@name="remoteTunnelEndpoint"]'}
            for node in nodes:
                if parameter in othe_ip_regex:
                    paramList.append(node.find(othe_ip_regex.get(parameter)).text)
        return paramList
